import sys

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    P = list(map(int, input().split()))

    def count_and_cost(x):
        total_count = 0
        total_cost = 0
        for p in P:
            c = (x // p + 1) // 2
            total_count += c
            total_cost += p * c * c
            if total_cost > M:
                return total_count, total_cost
        return total_count, total_cost

    low, high = 0, 10**30
    while high - low > 1:
        mid = (low + high) // 2
        _, cost = count_and_cost(mid)
        if cost <= M:
            low = mid
        else:
            high = mid

    count, cost = count_and_cost(low)
    answer = count + (M - cost) // high
    print(answer)

if __name__ == "__main__":
